-- Entity: yudao-module-mall/yudao-module-trade/src/main/java/cn/iocoder/yudao/module/trade/dal/dataobject/order/TradeOrderItemDO.java
-- Schema hints: yudao-module-mall/yudao-module-trade/src/test/resources/sql/create_tables.sql
CREATE TABLE IF NOT EXISTS `trade_order_item` (
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `creator` varchar(64) NULL DEFAULT '' COMMENT '创建者，目前使用 SysUser 的 id 编号',
  `updater` varchar(64) NULL DEFAULT '' COMMENT '更新者，目前使用 SysUser 的 id 编号',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id` bigint NULL COMMENT '用户编号',
  `order_id` bigint NULL COMMENT '订单编号',
  `cart_id` bigint NULL COMMENT '购物车项编号',
  `spu_id` bigint NULL COMMENT '商品 SPU 编号',
  `spu_name` longtext NULL COMMENT '商品 SPU 名称',
  `sku_id` bigint NULL COMMENT '商品 SKU 编号',
  `properties` json NULL COMMENT '属性数组，JSON 格式',
  `pic_url` longtext NULL COMMENT '商品图片',
  `count` int NULL COMMENT '购买数量',
  `comment_status` bit(1) NULL COMMENT '是否评价',
  `price` int NULL COMMENT '商品原价（单），单位：分',
  `discount_price` int NULL COMMENT '优惠金额（总），单位：分',
  `delivery_price` int NULL COMMENT '运费金额（总），单位：分',
  `adjust_price` int NULL COMMENT '订单调价（总），单位：分',
  `pay_price` int NULL COMMENT '应付金额（总），单位：分',
  `coupon_price` int NULL COMMENT '优惠劵减免金额，单位：分',
  `point_price` int NULL COMMENT '积分抵扣的金额，单位：分',
  `use_point` int NULL COMMENT '使用的积分',
  `give_point` int NULL COMMENT '赠送的积分',
  `vip_price` int NULL COMMENT 'VIP 减免金额，单位：分',
  `after_sale_id` bigint NULL COMMENT '售后单编号',
  `after_sale_status` int NULL COMMENT '售后状态',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号（租户拦截器写入）',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_deleted` (`tenant_id`, `deleted`),
  KEY `idx_user_id` (`tenant_id`, `user_id`),
  KEY `idx_order_id` (`tenant_id`, `order_id`),
  KEY `idx_cart_id` (`tenant_id`, `cart_id`),
  KEY `idx_spu_id` (`tenant_id`, `spu_id`),
  KEY `idx_sku_id` (`tenant_id`, `sku_id`),
  KEY `idx_after_sale_id` (`tenant_id`, `after_sale_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='交易订单项 DO';

