  KEY `idx_tenant_deleted` (`tenant_id`, `deleted`),
  KEY `idx_user_id` (`tenant_id`, `user_id`),
  KEY `idx_order_id` (`tenant_id`, `order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='订单日志 DO';

-- Entity: yudao-module-mall/yudao-module-statistics/src/main/java/cn/iocoder/yudao/module/statistics/dal/dataobject/trade/TradeStatisticsDO.java
CREATE TABLE IF NOT EXISTS `trade_statistics` (
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `creator` varchar(64) NULL DEFAULT '' COMMENT '创建者，目前使用 SysUser 的 id 编号',
  `updater` varchar(64) NULL DEFAULT '' COMMENT '更新者，目前使用 SysUser 的 id 编号',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号，主键自增',
  `time` datetime(6) NULL COMMENT '统计日期',
  `order_create_count` int NULL COMMENT '创建订单数',
  `order_pay_count` int NULL COMMENT '支付订单商品数',
  `order_pay_price` int NULL COMMENT '总支付金额，单位：分',
  `after_sale_count` int NULL COMMENT '退款订单数',
  `after_sale_refund_price` int NULL COMMENT '总退款金额，单位：分',
  `brokerage_settlement_price` int NULL COMMENT '佣金金额（已结算），单位：分',
  `wallet_pay_price` int NULL COMMENT '总支付金额（余额），单位：分',
  `recharge_pay_count` int NULL COMMENT '充值订单数',
  `recharge_pay_price` int NULL COMMENT '充值金额，单位：分',
  `recharge_refund_count` int NULL COMMENT '充值退款订单数',
  `recharge_refund_price` int NULL COMMENT '充值退款金额，单位：分',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号（租户拦截器写入）',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_deleted` (`tenant_id`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='交易统计 DO';
